{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 7,
      "text_ar": "After seven days the world that is not yet awake will be raised up, and what is corruptible will die.",
      "verse": 31
    },
    {
      "chapter": 7,
      "text_ar": "The earth will restore those who are asleep in it, and the dust those who dwell in it in silence, and the secret places will deliver those souls that were committed to them.",
      "verse": 32
    },
    {
      "chapter": 7,
      "text_ar": "The Most High will be revealed on the judgment seat, and compassion will pass away, and patience will be withdrawn.",
      "verse": 33
    },
    {
      "chapter": 7,
      "text_ar": "Only judgment will remain. Truth will stand. Faith will grow strong.",
      "verse": 34
    },
    {
      "chapter": 7,
      "text_ar": "Recompense will follow. The reward will be shown. Good deeds will awake, and wicked deeds won't sleep.",
      "verse": 35
    },
    {
      "chapter": 7,
      "text_ar": "The pit of torment will appear, and near it will be the place of rest. The furnace of hell will be shown, and near it the paradise of delight.",
      "verse": 36
    },
    {
      "chapter": 7,
      "text_ar": "Then the Most High will say to the nations that are raised from the dead, Look and understand whom you have denied, whom you haven't served, whose commandments you have despised.",
      "verse": 37
    },
    {
      "chapter": 7,
      "text_ar": "Look on this side and on that. Here is delight and rest, and there fire and torments. Thus he will speak to them in the day of judgment.",
      "verse": 38
    },
    {
      "chapter": 7,
      "text_ar": "This is a day that has neither sun, nor moon, nor stars,",
      "verse": 39
    },
    {
      "chapter": 7,
      "text_ar": "neither cloud, nor thunder, nor lightning, neither wind, nor water, nor air, neither darkness, nor evening, nor morning,",
      "verse": 40
    }
  ]
}
